void solve(int CASE)
{
	ll n, s, t, x; cin >> n >> s >> t >> x;
	var g = vector<vector<int>>(n + 2);
	fa(i, 1, n - 1) {
		int u, v; cin >> u >> v;
		g[u].pb(v), g[v].pb(u);
	}
	var a = vector<ll>(n + 2);
	fa(i, 1, n)cin >> a[i];

	// 1. 找到 S 到 T 的唯一路径（链）：链上的怪必须打，代价先扣掉
	var vis = vector<bool>(n + 2);
	var par = vector<int>(n + 2);
	var lian = vector<int>();
	int ans = 0;
	var dfs = [&](var dfs, int now, int fa)->void {
		par[now] = fa;
		if (now == t) {
			int cur = now;
			while (cur != s) {
				vis[cur] = 1;
				lian.pb(cur);
				ans++, x -= a[cur];
				cur = par[cur];
			}
			vis[cur] = 1;
			lian.pb(cur);
			ans++, x -= a[cur];
		}
		for (int to : g[now]) {
			if (to == fa)continue;
			dfs(dfs, to, now);
		}
		};
	dfs(dfs, s, 0);

	// 血量归零即死：路径伤害 >= X 时连出口都到不了
	if (x <= 0) {
		cout << -1 << endl;
		return;
	}

	// 2. 链上每个点挂出去的子树，全部接到虚拟根 super 上
	// 这样"钻进子树再绕回来"的代价就等于子树内部的代价（链上的怪已经死过了）
	int super = n + 1;
	for (int x : lian) { // 注意：这里的 x 是房间号，遮蔽了上面的血量 x
		for (int to : g[x])if (!vis[to]) {
			g[super].pb(to);
			g[to].pb(super);
		}
	}

	// 3. 树上背包：dp[u][i] = 以 u 为根、必选 u、共选 i 个点的最小代价
	var dp = Vec2<int>(n + 2, n + 2, INF);
	fa(i, 1, n + 1)dp[i][0] = 0;
	var siz = vector<int>(n + 2);
	var dfss = [&](var dfs, int now, int fa)->void {
		siz[now] = 1;
		var p = vector<int>();
		for (int to : g[now]) {
			if (vis[to] or to == fa)continue;
			dfs(dfs, to, now);
			siz[now] += siz[to];
			p.pb(to);
		}

		int add = 0; // 已经拿下 add 个节点
		for (int to : p) {
			// 孩子 = 一组，容量维 i 必须在外层倒序，j 是组内选项（从这棵子树里选 j 个点）
			fb(i, siz[to] + add, 1)
				fa(j, max(1, i - add), min(i, siz[to]))
					dp[now][i] = min(dp[now][i], dp[now][i - j] + dp[to][j]);
			add += siz[to];
		}
		// 整体右移一位，把 now 自己算进去
		fb(i, siz[now], 1)dp[now][i] = dp[now][i - 1] + a[now];
		};
	dfss(dfss, super, 0);

	// 4. 从大到小找第一个"代价 < 剩余血量"的点数（dp[super][i] 关于 i 单调不减）
	fb(i, siz[super], 1) {
		if (x > dp[super][i]) {
			ans += i - 1; // i 里含虚拟根，实际多打 i - 1 只
			break;
		}
	}

	// 链上的 S / T 没有怪，要减掉；S == T 时只减一次
	if (s == t)cout << ans - 1 << endl;
	else cout << ans - 2 << endl;
	return;
}
